(()=>{
 const dialog=document.createElement('dialog');dialog.className='bbstore-modules';dialog.setAttribute('aria-labelledby','checkout-title');
 dialog.innerHTML='<div class="bbstore-menu-heading"><h2 id="checkout-title">Subscription checkout</h2><button type="button" data-checkout-close aria-label="Close checkout">✕</button></div><p data-checkout-plan></p><p data-checkout-price></p><p data-checkout-note>Payment collection is not connected. Saving a request does not charge you or activate a subscription.</p><p data-checkout-status role="status"></p><button type="button" class="bbstore-nav-button" data-checkout-confirm disabled>Save package request</button>';
 document.body.append(dialog);const confirm=dialog.querySelector('[data-checkout-confirm]'),status=dialog.querySelector('[data-checkout-status]');let current=null,opening=false;
 dialog.querySelector('[data-checkout-close]').onclick=()=>dialog.close();
 window.bongaCheckout=async(tier,trigger)=>{if(opening)return;opening=true;current=null;confirm.disabled=true;status.textContent='Loading package price…';dialog.querySelector('[data-checkout-plan]').textContent='';dialog.querySelector('[data-checkout-price]').textContent='';if(!dialog.open)dialog.showModal();try{const r=await fetch('/api/public/checkout?tier='+encodeURIComponent(tier)),data=await r.json();if(!r.ok)throw Error(data.error||'Checkout unavailable.');current=data.subscription;dialog.querySelector('[data-checkout-plan]').textContent=current.name+' subscription';dialog.querySelector('[data-checkout-price]').textContent=new Intl.NumberFormat('en-ZA',{style:'currency',currency:current.currency}).format(current.amountMinor/100)+' per month';status.textContent='Price confirmed from the package catalogue.';confirm.disabled=false;}catch(e){status.textContent=e.message||'Checkout unavailable.';}finally{opening=false;}};
 confirm.onclick=async()=>{if(!current)return;confirm.disabled=true;status.textContent='Saving your package request…';try{const r=await fetch('/api/designer/package',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tier:current.tier})}),data=await r.json();if(r.status===401){sessionStorage.setItem('bonga-requested-tier',current.tier);location.href='/signin-with-chatgpt?return_to='+encodeURIComponent('/?checkout='+current.tier+'#packages');return;}if(!r.ok)throw Error(data.error||'Request unavailable.');status.textContent=data.subscription.name+' · '+new Intl.NumberFormat('en-ZA',{style:'currency',currency:data.subscription.currency}).format(data.subscription.amountMinor/100)+' per month. '+data.status;document.getElementById('package-state').textContent=status.textContent;}catch(e){status.textContent=e.message||'Request unavailable.';confirm.disabled=false;}};
 const tier=new URLSearchParams(location.search).get('checkout');if(tier)window.bongaCheckout(tier);
})();
